Pitfall ID: P13
Pitfall Name: Inverse relationships not explicitly declared
Pitfall Description: This pitfall appears when any relationship (except for those that are defined as symmetric properties using owl:SymmetricProperty) does not have an inverse relationship (owl:inverseOf) defined within the ontology.
Affected Element: http://www.softlang.org/ontologies/tbox#hasOutputArtifact

### Ontology context (Turtle)
```turtle
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix foaf: <http://xmlns.com/foaf/0.1/> .
@prefix ae: <http://www.softlang.org/ontologies/ae#> .
@prefix ce: <http://www.softlang.org/ontologies/ce#> .
@prefix fe: <http://www.softlang.org/ontologies/fe#> .
@prefix le: <http://www.softlang.org/ontologies/le#> .
@prefix pe: <http://www.softlang.org/ontologies/pe#> .
@prefix tbox: <http://www.softlang.org/ontologies/tbox#> .
@prefix te: <http://www.softlang.org/ontologies/te#> .

ce:APIDesign a tbox:ConceptualEntity ;
    rdfs:label "API design"@en ;
    tbox:hasOutputArtifact ae:APIDescriptionArtifact ;
    tbox:hasSupportingLanguage le:InterfaceDescriptionLanguage ;
    tbox:hasSupportingTool te:APIWorkbench ;
    tbox:uses fe:SoftwareDesignApproach ;
    rdfs:subClassOf ce:InterfaceDesign ;
    foaf:page <https://en.wikipedia.org/wiki/API> .

ce:BuildScripting a tbox:ConceptualEntity ;
    rdfs:label "Build scripting"@en ;
    tbox:hasOutputArtifact ae:BuildScriptArtifact ;
    tbox:hasSupportingLanguage le:BuildScriptingLanguage ;
    tbox:hasSupportingTool te:BuildTool ;
    rdfs:subClassOf ce:ImplementationActivity ;
    foaf:page <https://en.wikipedia.org/wiki/Build_automation> .

ce:CodeGeneration a tbox:ConceptualEntity ;
    rdfs:label "Code generation"@en ;
    tbox:hasInputArtifact ae:GrammarArtifact,
        ae:ModelArtifact ;
    tbox:hasOutputArtifact ae:ProgramArtifact ;
    tbox:hasSupportingLanguage le:ModelTransformationLanguage,
        pe:ProgrammingLanguage ;
    tbox:hasSupportingTool te:ModelTransformationEngine ;
    tbox:uses fe:MetaprogrammingApproach ;
    rdfs:subClassOf ce:Implementation ;
    foaf:isPrimaryTopicOf <https://dbpedia.org/resource/Code_generation_(compiler)>,
        <https://en.wikipedia.org/wiki/Code_generation_(compiler)> ;
    foaf:page <https://en.wikipedia.org/wiki/Code_generation_(compiler)> .

ce:Coding a tbox:ConceptualEntity ;
    rdfs:label "Coding"@en ;
    tbox:hasOutputArtifact ae:ProgramArtifact ;
    tbox:hasSupportingLanguage pe:ProgrammingLanguage ;
    tbox:hasSupportingTool te:Compiler,
        te:Interpreter ;
    rdfs:subClassOf ce:Implementation ;
    foaf:page <https://en.wikipedia.org/wiki/Computer_programming> .

ce:Implementation a tbox:ConceptualEntity ;
    rdfs:label "Implementation"@en ;
    tbox:hasOutputArtifact ae:ProgramArtifact ;
    tbox:hasSupportingLanguage pe:ProgrammingLanguage ;
    tbox:hasSupportingTool te:Compiler,
        te:Interpreter ;
    tbox:uses fe:SoftwareDesignApproach ;
    rdfs:subClassOf ce:ImplementationActivity ;
    foaf:isPrimaryTopicOf <https://en.wikipedia.org/wiki/Implementation> .

ce:InterfaceDesign a tbox:ConceptualEntity ;
    rdfs:label "Interface design"@en ;
    tbox:hasOutputArtifact ae:APIDescriptionArtifact ;
    tbox:hasSupportingLanguage le:InterfaceDescriptionLanguage ;
    tbox:hasSupportingTool te:APIWorkbench ;
    tbox:uses fe:SoftwareDesignApproach ;
    rdfs:subClassOf ce:DesignActivity ;
    foaf:page <https://en.wikipedia.org/wiki/Interface_(computing)> .

ce:Programming a tbox:ConceptualEntity ;
    rdfs:label "Programming"@en ;
    tbox:hasOutputArtifact ae:ProgramArtifact ;
    tbox:hasSupportingLanguage pe:ProgrammingLanguage ;
    tbox:hasSupportingTool te:Compiler,
        te:Interpreter ;
    tbox:uses fe:ModelOfComputation ;
    rdfs:subClassOf ce:Coding ;
    foaf:isPrimaryTopicOf <https://en.wikipedia.org/wiki/Computer_programming> .

ce:Prototyping a tbox:ConceptualEntity ;
    rdfs:label "Prototyping"@en ;
    tbox:hasOutputArtifact ae:ModelArtifact,
        ae:ProgramArtifact ;
    tbox:hasSupportingLanguage le:ModelingLanguage,
        pe:ProgrammingLanguage ;
    tbox:uses fe:SoftwareDesignApproach ;
    rdfs:subClassOf ce:DesignValidation ;
    foaf:isPrimaryTopicOf <https://en.wikipedia.org/wiki/Software_prototyping> .

ce:RequirementsSpecification a tbox:ConceptualEntity ;
    rdfs:label "Requirements specification"@en ;
    tbox:hasOutputArtifact ae:RequirementsArtifact ;
    tbox:hasSupportingLanguage le:RequirementsSpecificationLanguage ;
    tbox:hasSupportingTool te:RequirementsTool ;
    rdfs:subClassOf ce:RequirementsEngineeringActivity ;
    foaf:isPrimaryTopicOf <https://en.wikipedia.org/wiki/Software_requirements_specification> .

tbox:hasOutputArtifact a owl:ObjectProperty,
        tbox:PropertyEntity ;
    rdfs:label "has output artifact"@en ;
    rdfs:comment "Relates an activity or a tool to an artifact kind that it typically produces as output"@en ;
    foaf:page <https://en.wikipedia.org/wiki/Artifact_(software_development)> ;
    rdfs:domain [ a owl:Class ;
            owl:unionOf ( tbox:EngineeringActivity tbox:ToolEntity ) ] ;
    rdfs:range tbox:ArtifactEntity .

te:APIWorkbench a tbox:ToolEntity ;
    rdfs:label "API workbench"@en ;
    tbox:hasAffectedArtifact ae:APIDescriptionArtifact ;
    tbox:hasInputArtifact ae:APIDescriptionArtifact ;
    tbox:hasOutputArtifact ae:APIDescriptionArtifact ;
    tbox:processes ae:APIDescriptionArtifact ;
    tbox:targets le:InterfaceDescriptionLanguage ;
    rdfs:subClassOf tbox:SoftwareTool .

te:Compiler a tbox:ToolEntity ;
    rdfs:label "Compiler"@en ;
    tbox:hasInputArtifact ae:ProgramArtifact ;
    tbox:hasOutputArtifact ae:ProgramArtifact ;
    tbox:processes ae:ProgramArtifact ;
    tbox:targets pe:ProgrammingLanguage ;
    rdfs:subClassOf tbox:SoftwareTool .

te:ConfigurationTool a tbox:ToolEntity ;
    rdfs:label "Configuration tool"@en ;
    tbox:hasAffectedArtifact ae:ConfigurationArtifact ;
    tbox:hasInputArtifact ae:ConfigurationArtifact ;
    tbox:hasOutputArtifact ae:ConfigurationArtifact ;
    tbox:targets le:ConfigurationLanguage ;
    rdfs:subClassOf tbox:SoftwareTool ;
    foaf:page <https://en.wikipedia.org/wiki/Configuration_management> .

te:ModelTransformationEngine a tbox:ToolEntity ;
    rdfs:label "Model transformation engine"@en ;
    tbox:hasInputArtifact ae:MetamodelArtifact,
        ae:ModelArtifact ;
    tbox:hasOutputArtifact ae:ModelArtifact ;
    tbox:processes ae:MetamodelArtifact,
        ae:ModelArtifact ;
    tbox:targets le:ModelTransformationLanguage ;
    rdfs:subClassOf te:TransformationEngine .

te:ProofAssistant a tbox:ToolEntity ;
    rdfs:label "Proof assistant"@en ;
    tbox:hasAffectedArtifact ae:ProofArtifact ;
    tbox:hasInputArtifact ae:ProofArtifact ;
    tbox:hasOutputArtifact ae:ProofArtifact ;
    tbox:processes ae:ProofArtifact ;
    tbox:targets le:ProofLanguage ;
    rdfs:subClassOf tbox:SoftwareTool .

te:RequirementsTool a tbox:ToolEntity ;
    rdfs:label "Requirements tool"@en ;
    tbox:hasAffectedArtifact ae:RequirementsArtifact ;
    tbox:hasInputArtifact ae:RequirementsArtifact ;
    tbox:hasOutputArtifact ae:RequirementsArtifact ;
    tbox:targets le:RequirementsSpecificationLanguage ;
    rdfs:subClassOf tbox:SoftwareTool ;
    foaf:page <https://en.wikipedia.org/wiki/Requirements_engineering> .
```

Pitfall ID: P13
Pitfall Name: Inverse relationships not explicitly declared
Pitfall Description: This pitfall appears when any relationship (except for those that are defined as symmetric properties using owl:SymmetricProperty) does not have an inverse relationship (owl:inverseOf) defined within the ontology.
