pe:Haskell_StructuredComputationAbstractions_assertion a tbox:LanguageSupportAssertion ;
    tbox:assertedForConcept ce:StructuredComputationAbstractions ;
    tbox:assertedForLanguage pe:Haskell ;
    tbox:hasDominantForm ce:MonadicStyle ;
    tbox:hasPrimaryMechanism ce:TypeClassBasedMechanism ;
    tbox:hasSupportKind ce:NativeSupport ;
    skos:note "Representative native support centers on type classes and monadic style."@en .

pe:Java_ErrorHandling_assertion a tbox:LanguageSupportAssertion ;
    tbox:assertedForConcept ce:ErrorHandling ;
    tbox:assertedForLanguage pe:Java ;
    tbox:hasDominantForm ce:Exceptions ;
    tbox:hasPrimaryMechanism ce:ExceptionMechanism ;
    tbox:hasSupportKind ce:NativeSupport .

pe:Java_FuturesAndPromises_assertion a tbox:LanguageSupportAssertion ;
    tbox:assertedForConcept ce:FuturesAndPromises ;
    tbox:assertedForLanguage pe:Java ;
    tbox:hasDominantForm ce:AsyncEventDrivenConcurrency ;
    tbox:hasPrimaryMechanism ce:TaskLibraryMechanism ;
    tbox:hasSupportKind ce:StandardLibrarySupport .

pe:Java_Objects_assertion a tbox:LanguageSupportAssertion ;
    tbox:assertedForConcept ce:Objects ;
    tbox:assertedForLanguage pe:Java ;
    tbox:hasDominantForm ce:ObjectOrientedParadigm ;
    tbox:hasPrimaryMechanism ce:ClassBasedMechanism ;
    tbox:hasSupportKind ce:NativeSupport .

pe:Koka_EffectHandlerStyle_assertion a tbox:LanguageSupportAssertion ;
    tbox:assertedForConcept ce:EffectHandlerStyle ;
    tbox:assertedForLanguage pe:Koka ;
    tbox:hasDominantForm ce:EffectHandlerStyle ;
    tbox:hasPrimaryMechanism ce:EffectHandlerMechanism ;
    tbox:hasSupportKind ce:NativeSupport ;
    skos:note "Representative exercise language for effect-handler style."@en .

pe:Prolog_ComputationalParadigmsAndEvaluationModels_assertion a tbox:LanguageSupportAssertion ;
    tbox:assertedForConcept ce:ComputationalParadigmsAndEvaluationModels ;
    tbox:assertedForLanguage pe:Prolog ;
    tbox:hasDominantForm ce:LogicParadigm ;
    tbox:hasPrimaryMechanism ce:RuleAndPredicateMechanism ;
    tbox:hasSupportKind ce:NativeSupport ;
    skos:note "Representative support centers on logic programming and rule/predicate execution."@en .

pe:Prolog_ControlFlow_assertion a tbox:LanguageSupportAssertion ;
    tbox:assertedForConcept ce:ControlFlow ;
    tbox:assertedForLanguage pe:Prolog ;
    tbox:hasDominantForm ce:Backtracking ;
    tbox:hasPrimaryMechanism ce:BacktrackingMechanism ;
    tbox:hasSupportKind ce:NativeSupport .

pe:Python_IteratorsAndGenerators_assertion a tbox:LanguageSupportAssertion ;
    tbox:assertedForConcept ce:IteratorsAndGenerators ;
    tbox:assertedForLanguage pe:Python ;
    tbox:hasDominantForm ce:Coroutines ;
    tbox:hasPrimaryMechanism ce:GeneratorProtocolMechanism ;
    tbox:hasSupportKind ce:NativeSupport .

pe:Python_Objects_assertion a tbox:LanguageSupportAssertion ;
    tbox:assertedForConcept ce:Objects ;
    tbox:assertedForLanguage pe:Python ;
    tbox:hasDominantForm ce:ObjectOrientedParadigm ;
    tbox:hasPrimaryMechanism ce:ClassBasedMechanism ;
    tbox:hasSupportKind ce:NativeSupport .

pe:Scheme_ContinuationPassingStyle_assertion a tbox:LanguageSupportAssertion ;
    tbox:assertedForConcept ce:ContinuationPassingStyle ;
    tbox:assertedForLanguage pe:Scheme ;
    tbox:hasDominantForm ce:ContinuationPassingStyle ;
    tbox:hasPrimaryMechanism ce:ContinuationOperatorMechanism ;
    tbox:hasSupportKind ce:NativeSupport ;
    skos:note "Representative exercise language for continuation-passing style."@en .

tbox:hasPrimaryMechanism a owl:ObjectProperty ,
        tbox:PropertyEntity ;
    rdfs:label "Has primary mechanism"@en ;
    rdfs:domain tbox:LanguageSupportAssertion ;
    rdfs:range tbox:ImplementationMechanismConcept ;
    rdfs:comment "Relates a reified assertion about language concepts with the primary mechanism for realization"@en ;
    foaf:page <https://en.wikipedia.org/wiki/Category:Programming_language_concepts> .
```

