Pitfall ID: P13
Pitfall Name: Inverse relationships not explicitly declared
Pitfall Description: This pitfall appears when any relationship (except for those that are defined as symmetric properties using owl:SymmetricProperty) does not have an inverse relationship (owl:inverseOf) defined within the ontology.
Affected Element: http://www.softlang.org/ontologies/tbox#hasPrimaryComponent

### Ontology context (Turtle)
```turtle
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix foaf: <http://xmlns.com/foaf/0.1/> .
@prefix ce: <http://www.softlang.org/ontologies/ce#> .
@prefix tbox: <http://www.softlang.org/ontologies/tbox#> .

ce:Actors a tbox:CompositeConcept,
        tbox:ConceptualEntity ;
    rdfs:label "Actors"@en ;
    tbox:hasPrimaryComponent ce:ActorBasedConcurrency,
        ce:Encapsulation,
        ce:VariablesAsState ;
    tbox:hasSecondaryComponent ce:MessagePassingConcurrency,
        ce:Modules,
        ce:SideEffects ;
    foaf:isPrimaryTopicOf <https://dbpedia.org/resource/Actor_model> ;
    foaf:page <https://en.wikipedia.org/wiki/Actor_model> .

ce:AlgebraicDataTypes a tbox:CompositeConcept,
        tbox:ConceptualEntity ;
    rdfs:label "Algebraic data types"@en ;
    tbox:hasPrimaryComponent ce:DataAbstraction,
        ce:ParametricPolymorphism,
        ce:ProductLikeData,
        ce:SumLikeData ;
    tbox:hasSecondaryComponent ce:ModuleAbstraction,
        ce:RecursiveData ;
    foaf:isPrimaryTopicOf <https://dbpedia.org/resource/Algebraic_data_type> ;
    foaf:page <https://en.wikipedia.org/wiki/Algebraic_data_type> .

ce:Closures a tbox:CompositeConcept,
        tbox:ConceptualEntity ;
    rdfs:label "Closures"@en ;
    tbox:hasPrimaryComponent ce:FirstClassFunctions,
        ce:FunctionAbstraction,
        ce:HeapLifetime,
        ce:LexicalScope,
        ce:NameBinding ;
    tbox:hasSecondaryComponent ce:Records ;
    foaf:isPrimaryTopicOf <https://dbpedia.org/resource/Closure_(computer_programming)> ;
    foaf:page <https://en.wikipedia.org/wiki/Closure_(computer_programming)> .

ce:FuturesAndPromises a tbox:CompositeConcept,
        tbox:ConceptualEntity ;
    rdfs:label "Futures and promises"@en ;
    tbox:hasPrimaryComponent ce:AsyncEventDrivenConcurrency,
        ce:IOEffects ;
    tbox:hasSecondaryComponent ce:Continuations,
        ce:ErrorHandling ;
    foaf:isPrimaryTopicOf <https://dbpedia.org/resource/Futures_and_promises> ;
    foaf:page <https://en.wikipedia.org/wiki/Futures_and_promises> .

ce:IteratorsAndGenerators a tbox:CompositeConcept,
        tbox:ConceptualEntity ;
    rdfs:label "Iterators and generators"@en ;
    tbox:hasPrimaryComponent ce:Iteration,
        ce:ProceduralAbstraction,
        ce:VariablesAsState ;
    tbox:hasSecondaryComponent ce:Coroutines,
        ce:FirstClassFunctions ;
    foaf:page <https://en.wikipedia.org/wiki/Generator_(computer_programming)>,
        <https://en.wikipedia.org/wiki/Iterator> .

ce:Objects a tbox:CompositeConcept,
        tbox:ConceptualEntity ;
    rdfs:label "Objects"@en ;
    tbox:hasPrimaryComponent ce:Encapsulation,
        ce:InterfacesAndContracts,
        ce:ObjectsAsData ;
    tbox:hasSecondaryComponent ce:CompositionVsInheritance,
        ce:MutableData,
        ce:SideEffects,
        ce:VariablesAsState ;
    foaf:isPrimaryTopicOf <https://dbpedia.org/resource/Object_(computer_science)> ;
    foaf:page <https://en.wikipedia.org/wiki/Object_(computer_science)> .

ce:StructuredComputationAbstractions a tbox:CompositeConcept,
        tbox:ConceptualEntity ;
    rdfs:label "Structured computation abstractions"@en ;
    tbox:hasPrimaryComponent ce:FunctionAbstraction,
        ce:HigherOrderFunctions,
        ce:TypeAbstraction ;
    tbox:hasSecondaryComponent ce:ApplicativeStyle,
        ce:ArrowStyle,
        ce:ContinuationPassingStyle,
        ce:EffectHandlerStyle,
        ce:MonadicStyle,
        ce:OptionResultTypes,
        ce:PipelineStyle,
        ce:SideEffects ;
    foaf:page <https://en.wikipedia.org/wiki/Applicative_functor>,
        <https://en.wikipedia.org/wiki/Arrow_(computer_science)>,
        <https://en.wikipedia.org/wiki/Monad_(functional_programming)> .

tbox:hasPrimaryComponent a owl:ObjectProperty ,
        tbox:PropertyEntity ;
    rdfs:label "Has primary component"@en ;
    rdfs:domain tbox:CompositeConcept ;
    rdfs:range tbox:LanguageConcept ;
    rdfs:subPropertyOf tbox:hasComponent ;
    rdfs:comment "Relates a composite language concept to a (primary) component"@en ;
    foaf:page <https://en.wikipedia.org/wiki/Category:Programming_language_concepts> .
```

